juce::AudioProcessorValueTreeState::ParameterLayout createParameterLayout()
{
    juce::AudioProcessorValueTreeState::ParameterLayout layout;
    for (const auto& def : kParams)
    {
        if (def.type == ParamType::Toggle)
        {
            layout.add(std::make_unique<juce::AudioParameterBool>(
                juce::ParameterID(def.id, 1), def.name, false));
        }
        else if (def.type == ParamType::Enum)
        {
            juce::StringArray choices;
            for (int i = 0; i < def.numOptions; ++i)
                choices.add(kOptionStrings[def.firstOptionIndex + i]);
            if (choices.isEmpty())
                choices.add("Off");
            layout.add(std::make_unique<juce::AudioParameterChoice>(
                juce::ParameterID(def.id, 1), def.name, choices, 0));
        }
        else
        {
            layout.add(std::make_unique<juce::AudioParameterInt>(
                juce::ParameterID(def.id, 1), def.name, def.minValue, def.maxValue, def.minValue));
        }
    }
    return layout;
}

const std::map<int, int>& nrpnToParamIndex()
{
    static const std::map<int, int> table = [] {
        std::map<int, int> m;
        for (int i = 0; i < kNumParams; ++i)
        {
            m[kParams[i].nrpnA] = i;
            if (kParams[i].nrpnB >= 0)
                m[kParams[i].nrpnB] = i;
        }
        return m;
    }();
    return table;
}

